import Image from "next/image";

type Item = { id: string; title: string; description: string | null; mediaType: "IMAGE" | "VIDEO"; url: string };

export function GalleryGrid({ items }: { items: Item[] }) {
  if (!items.length) return <p className="text-sm text-muted">Project photos will appear here soon.</p>;
  return (
    <div className="grid grid-cols-2 gap-3 md:grid-cols-3">
      {items.map((g) => (
        <figure key={g.id} className="overflow-hidden rounded-lg border border-line bg-white">
          <div className="relative aspect-[4/3] bg-paper">
            {g.mediaType === "VIDEO" ? (
              <video src={g.url} controls preload="metadata" className="h-full w-full object-cover" />
            ) : (
              <Image src={g.url} alt={g.title} fill sizes="(max-width: 768px) 50vw, 33vw" className="object-cover" />
            )}
          </div>
          <figcaption className="p-3"><p className="text-sm font-semibold">{g.title}</p>{g.description && <p className="text-xs text-muted">{g.description}</p>}</figcaption>
        </figure>
      ))}
    </div>
  );
}
